<?php
require_once dirname(__DIR__) . '/_private/presentations.php';
$dateId=input_id($_GET,'date_id'); $slot=input_id($_GET,'slot');
try { $info=presentation_date($pdo,$dateId); } catch (DomainException $e) { app_error(404,$e->getMessage()); }
if ($slot > (int)$info['slots_per_date']) app_error(404,'Slot neexistuje.');
$stmt=$pdo->prepare('SELECT 1 FROM presentation_registrations WHERE date_id=? AND slot_number=? AND status="active"'); $stmt->execute([$dateId,$slot]);
if ($stmt->fetch()) app_error(409,'Slot je již obsazený.');
$globalCssPath='/studevid/css/global.css'; $dashboardCssPath=null; $extraCssFiles=['presentations.css']; $loadJquery=true; $loadChartJs=false; $loadDesignJs=false;
